function signaturePad(canvas,clear){
  const ctx=canvas.getContext('2d');let pointer=null,signed=false;const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};
  ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#111';canvas.onpointerdown=e=>{if(pointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();canvas.setPointerCapture(e.pointerId);pointer=e.pointerId;signed=true;const [x,y]=point(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.1,y+.1);ctx.stroke();};canvas.onpointermove=e=>{if(e.pointerId===pointer){const [x,y]=point(e);ctx.lineTo(x,y);ctx.stroke();}};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=e=>{if(!e||e.pointerId===pointer)pointer=null;};clear.onclick=()=>{pointer=null;ctx.clearRect(0,0,canvas.width,canvas.height);signed=false;};
  return ()=>{if(!signed)throw Error('시험 서명을 입력해 주세요.');return canvas.toDataURL('image/png');};
}
function showDialog(title, html, onSubmit, currentScope=()=>true, successMessage=()=> '저장했습니다.') {
  $('#dialog-title').textContent=title; $('#dialog-body').innerHTML=html; $('#dialog-error').textContent='';
  const form=$('#dialog-form'),submit=$('#dialog-form button[type=submit]');
  submit.textContent='저장';submit.disabled=false;
  const current=()=>form.onsubmit===save&&currentScope();
  async function save(e){
    e.preventDefault();if(!current()||!dialog.open||submit.disabled)return;submit.disabled=true;
    try{const result=await onSubmit(Object.fromEntries(new FormData(e.currentTarget)));if(!current()||!dialog.open)return;dialog.close();flash(successMessage(result));await render();}
    catch(err){if(current()&&dialog.open)$('#dialog-error').textContent=err.message;}
    finally{if(current())submit.disabled=false;}
  }
  form.onsubmit=save;
  dialog.showModal();
}
