  const controls=document.createElement('fieldset'),notice=document.createElement('p'),allLabel=document.createElement('label'),all=document.createElement('input'),inputs=[];controls.className='risk-display-controls';controls.innerHTML='<legend>위험요인 표시 선택</legend><p>선택은 이 화면에만 적용되며 저장된 내용은 바뀌지 않습니다.</p>';notice.setAttribute('role','status');all.type='checkbox';all.checked=true;allLabel.append(all,document.createTextNode(' 전체 선택 '));controls.append(allLabel);
  const update=()=>{for(const {input,labels} of inputs)for(const item of rows)if(labels.includes(item.label))item.row.hidden=!input.checked;const count=inputs.filter(({input})=>input.checked).length;all.checked=count===inputs.length;all.indeterminate=count>0&&count<inputs.length;notice.textContent=count<inputs.length?'일부 위험요인 표시 항목이 생략되어 있습니다.':'';};
