    content.innerHTML=`<section class="panel"><h2>시험 현장 위치 확인</h2><p>기본적으로 꺼져 있습니다. 설정하면 근로자의 시험 로그인·QR 재접속·퇴근 기록 때 기기 위치를 요청하고 통과한 좌표·정확도·시각을 이 현장의 시험 기록에 저장합니다. 기기 위치는 조작될 수 있으므로 실제 출입의 증거가 아닙니다.</p><form id="location-policy"><label><input type="checkbox" name="enabled" ${policy.enabled?'checked':''}> 시험 위치 확인 사용</label><div class="fields"><label>기준 위도<input name="latitude" type="number" step="any" min="-90" max="90" value="${esc(policy.latitude??'')}"></label><label>기준 경도<input name="longitude" type="number" step="any" min="-180" max="180" value="${esc(policy.longitude??'')}"></label><label>허용 반경 (m)<input name="radiusMeters" type="number" step="1" min="10" max="100000" value="${esc(policy.radiusMeters??100)}"></label><label>허용 위치 오차 (m)<input name="maxAccuracyMeters" type="number" step="1" min="1" max="100000" value="${esc(policy.maxAccuracyMeters??50)}"></label></div><p>설정을 끄더라도 이미 저장된 위치 기록은 남습니다. 실제 위치 대신 가상 좌표만 사용하세요.</p><button type="submit">시험 위치 설정 저장</button></form><h3>시험 위치 기록</h3><label>조회일 <input id="location-date" type="date" value="${esc(date)}"></label> <button type="button" id="location-search">조회</button>${events.length?`<div class="table-wrap"><table><thead><tr><th>근로자</th><th>기기 좌표</th><th>위치 오차</th><th>기준점 거리</th><th>확인 시각</th><th>관리</th></tr></thead><tbody>${events.map(event=>`<tr><td>${esc(event.name)}</td><td>${esc(event.latitude)}, ${esc(event.longitude)}${mapLink(event)}</td><td>${esc(event.accuracy_meters)} m</td><td>${esc(event.distance_meters)} m</td><td>${esc(new Date(event.checked_at).toLocaleString('ko-KR'))}</td><td><button type="button" data-location-delete="${event.id}" data-location-version="${esc(event.version)}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:'<p>해당 날짜의 시험 위치 기록이 없습니다.</p>'}</section>`;
    content.insertAdjacentHTML('beforeend',`<section class="panel"><h3>시험 퇴근 기록</h3><p>가상 기록이며 실제 근로시간이나 퇴근을 증명하지 않습니다. 위치 확인이 꺼진 경우 좌표는 저장하지 않습니다.</p>${departures.length?`<div class="table-wrap"><table><thead><tr><th>근로자</th><th>기기 좌표</th><th>위치 오차</th><th>기준점 거리</th><th>퇴근 시각</th><th>관리</th></tr></thead><tbody>${departures.map(item=>`<tr><td>${esc(item.name)}</td><td>${item.latitude===null?'위치 기록 없음':`${esc(item.latitude)}, ${esc(item.longitude)}${mapLink(item)}`}</td><td>${item.accuracy_meters===null?'-':`${esc(item.accuracy_meters)} m`}</td><td>${item.distance_meters===null?'-':`${esc(item.distance_meters)} m`}</td><td>${esc(new Date(item.checked_at).toLocaleString('ko-KR'))}</td><td><button type="button" data-departure-id="${item.id}" data-departure-version="${esc(item.version)}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:'<p>해당 날짜의 시험 퇴근 기록이 없습니다.</p>'}</section>`);
    content.insertAdjacentHTML('beforeend',`<section class="panel"><h3>시험 첫 접속 시각</h3><p>가상 로그인이나 QR 재접속으로 기록한 해당 날짜의 첫 접속입니다. 삭제 후 같은 날 다시 접속하면 새로 기록됩니다. 기존 자료는 새로 추정하지 않으며 실제 출근을 증명하지 않습니다.</p>${arrivals.length?`<div class="table-wrap"><table><thead><tr><th>근로자</th><th>첫 접속 시각</th><th>관리</th></tr></thead><tbody>${arrivals.map(item=>`<tr><td>${esc(item.name)}</td><td>${esc(new Date(item.checked_at).toLocaleString('ko-KR'))}</td><td><button type="button" data-arrival-id="${item.worker_id}" data-arrival-version="${esc(item.version)}">삭제</button></td></tr>`).join('')}</tbody></table></div>`:'<p>해당 날짜의 시험 첫 접속 기록이 없습니다.</p>'}</section>`);
    content.insertAdjacentHTML('afterbegin',`<section class="panel"><h2>출입자별 시험 접속·퇴근</h2><p>조회일: ${esc(date)}. 구분·소속·직종과 생년월일은 현재 출입자 정보입니다. 접속 위치는 첫 접속과 연결된 위치라고 단정할 수 없어 각각의 확인 시각으로 표시합니다. 상세 기록의 삭제와 날짜 변경은 아래에서 할 수 있습니다.</p>${people.size?`<div class="table-wrap"><table><thead><tr><th>구분</th><th>이름</th><th>생년월일</th><th>소속</th><th>직종</th><th>첫 접속 시각</th><th>접속 위치 기록</th><th>퇴근 기록</th></tr></thead><tbody>${[...people.values()].map(person=>`<tr><td>${esc(person.category)}</td><td>${esc(person.name)}</td><td>${esc(person.birth_date||'-')}</td><td>${esc(person.company||'-')}</td><td>${esc(person.occupation||'-')}</td><td>${person.arrival?esc(new Date(person.arrival.checked_at).toLocaleString('ko-KR')):'-'}</td><td>${person.events.length?person.events.map(item=>`<div>${esc(new Date(item.checked_at).toLocaleString('ko-KR'))}${mapLink(item)}</div>`).join(''):'기록 없음'}</td><td>${person.departures.length?person.departures.map(item=>`<div>${esc(new Date(item.checked_at).toLocaleString('ko-KR'))}${mapLink(item)||' · 위치 기록 없음'}</div>`).join(''):'기록 없음'}</td></tr>`).join('')}</tbody></table></div>`:'<p>해당 날짜의 시험 접속·퇴근 기록이 없습니다.</p>'}</section>`);
    const form=$('#location-policy'),names=['latitude','longitude','radiusMeters','maxAccuracyMeters'],toggle=()=>{for(const name of names){form.elements[name].disabled=!form.elements.enabled.checked;form.elements[name].required=form.elements.enabled.checked;}};form.elements.enabled.onchange=toggle;toggle();
    form.onsubmit=async event=>{event.preventDefault();if(!current())return;const button=form.querySelector('button[type=submit]');button.disabled=true;try{const enabled=form.elements.enabled.checked,values=enabled?Object.fromEntries(names.map(name=>[name,Number(form.elements[name].value)])):{};await api(`${base}/location-policy`,{method:'PUT',body:JSON.stringify({enabled,expectedVersion:policy.version,...values})},current);if(current())await render();}catch(error){if(current())showError(error);}finally{button.disabled=false;}};
    $('#location-search').onclick=()=>{const value=$('#location-date').value;if(!value){flash('조회일을 선택해 주세요.',true);return;}state.workerLocationDate=value;render().catch(showError);};
    content.querySelectorAll('[data-location-delete]').forEach(button=>button.onclick=async()=>{if(!current()||!confirm('선택한 시험 위치 기록을 삭제할까요?'))return;button.disabled=true;try{await api(`${base}/location-events/${button.dataset.locationDelete}?version=${encodeURIComponent(button.dataset.locationVersion)}`,{method:'DELETE'},current);if(current())await render();}catch(error){if(current())showError(error);}finally{button.disabled=false;}});
    content.querySelectorAll('[data-arrival-id]').forEach(button=>button.onclick=async()=>{if(!current()||!confirm('선택한 시험 첫 접속 기록을 삭제할까요?'))return;button.disabled=true;try{await api(`${base}/worker-arrivals/${button.dataset.arrivalId}?date=${encodeURIComponent(date)}&version=${encodeURIComponent(button.dataset.arrivalVersion)}`,{method:'DELETE'},current);if(current())await render();}catch(error){if(current())showError(error);}finally{button.disabled=false;}});
